package cn.zj.zjmarket.verification;
import cn.zj.zjmarket.domain.order.adapter.repository.IOrderRepository;
import cn.zj.zjmarket.domain.payment.model.valobj.*;
import cn.zj.zjmarket.infrastructure.adapter.repository.*;
import cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec;
import cn.zj.zjmarket.infrastructure.gateway.mq.TradeMessageReader;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import static cn.zj.zjmarket.verification.ProductCommands.*;
final class RefundSyncAssertions {
 private static final ObjectMapper JSON=new ObjectMapper();
 private static byte[] bytes(Object value)throws Exception{return new ContractCodec().encode(value);}
 private static long count(JdbcTemplate db,String sql,Object...args){return db.queryForObject(sql,Long.class,args);}
 private static ObjectNode result(JdbcTemplate db,String refund,long version,String status){var f=db.queryForMap("SELECT * FROM b_refund WHERE refund_id=?",refund);var r=JSON.createObjectNode();r.put("outTradeNo",f.get("order_id").toString());r.put("refundId",refund);r.put("refundVersion",Long.toString(version));r.put("refundStatus",status);r.put("recordVersion","10");return r;}
 private static TradeReceipt receipt(String event,ObjectNode result,String authority)throws Exception{var p=JSON.createObjectNode();p.put("originalEventId",event);p.put("originalEventType","REFUND_STATUS_CHANGED");p.put("outcome","APPLIED");p.put("code","0000");p.put("info","owned controlled result");p.put("processedAt","2026-10-11T00:00:00.000Z");p.set("result",result);TradeMessageReader.validateResult(p);var e=new TreeMap<String,Object>();String id=UUID.randomUUID().toString();e.put("eventId",id);e.put("eventType","EVENT_PROCESSING_RESULT");e.put("schemaVersion",1);e.put("producer","group-buy-market");e.put("occurredAt","2026-10-11T00:00:00.000Z");e.put("source","s01");e.put("channel","c01");e.put("correlationId",event);e.put("payload",p);byte[] raw=bytes(e);return new TradeReceipt("group-buy-market",id,"EVENT_PROCESSING_RESULT",ContractCodec.sha256(raw),new String(raw,StandardCharsets.UTF_8),event,authority);}
 private static String authority(JdbcTemplate db,String refund,long version,String status)throws Exception{var f=db.queryForMap("SELECT * FROM b_refund WHERE refund_id=?",refund);var o=db.queryForMap("SELECT * FROM b_market_order WHERE order_id=?",f.get("order_id"));var a=(ObjectNode)JSON.readTree(o.get("a_evidence").toString());a.remove(List.of("paymentPresent","refundPresent"));var p=db.queryForMap("SELECT * FROM b_payment WHERE payment_id=?",f.get("payment_id"));a.put("recordVersion","10");a.put("teamStatus","FAILED");a.put("teamVersion","10");a.put("orderStatus","PAID");a.set("payment",JSON.valueToTree(Map.of("paymentId",f.get("payment_id"),"paidAmount",f.get("amount").toString(),"currency","CNY","paidAt",cn.zj.zjmarket.domain.payment.service.impl.PaymentService.time(((Number)p.get("paid_at_ms")).longValue()))));a.set("refund",JSON.valueToTree(Map.of("refundId",refund,"refundStatus",status,"refundVersion",Long.toString(version),"refundAmount",f.get("amount").toString(),"currency","CNY")));return new String(bytes(a),StandardCharsets.UTF_8);}
 static void run(DataSource ds,RefundRepository repo,SettlementRepository settlement,IOrderRepository orders,List<String> owned,Path work)throws Exception{var db=new JdbcTemplate(ds);settlement.enableRefundSync(repo,new RefundSyncRepository(db,repo,orders));
  // Backfill includes every previous-stage frozen version, even DONE or REVIEW_REQUIRED funds tasks.
  repo.backfillOutbox(10000);for(var f:db.queryForList("SELECT f.* FROM b_refund f JOIN b_market_order o ON o.order_id=f.order_id WHERE JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.source'))='s01' AND JSON_UNQUOTE(JSON_EXTRACT(o.a_evidence,'$.channel'))='c01' AND fact_version>0")){long frozen=count(db,"SELECT COUNT(*)+COALESCE(SUM(result_version IS NOT NULL),0) FROM b_refund_attempt WHERE refund_id=?",f.get("refund_id"));check(frozen==count(db,"SELECT COUNT(*) FROM b_trade_outbox WHERE refund_id=?",f.get("refund_id")),"all immutable versions backfilled, including terminal/review");}
  var prior=db.queryForList("SELECT event_id,body_hash,HEX(body) AS wire FROM b_trade_outbox ORDER BY event_id");repo.backfillOutbox(10000);check(prior.equals(db.queryForList("SELECT event_id,body_hash,HEX(body) AS wire FROM b_trade_outbox ORDER BY event_id")),"backfill idempotently preserves event IDs and wire bytes");
  String normal=owned.get(0),event=RefundOutbox.eventId(normal,1);db.update("UPDATE b_trade_outbox SET state='READY',next_attempt_ms=0,lease_token=NULL,lease_until_ms=NULL WHERE event_id=?",event);var delivery=settlement.claim(event);check(delivery!=null,"refund delivery claim");settlement.delivered(delivery,true,null);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND accepted_version=0",normal)==1,"broker ACK is not A acceptance");
  for(boolean replace:List.of(false,true))RefundCommands.lockedWait(ds,"b_trade_outbox","event_id",event,replace,watched->{var wdb=new JdbcTemplate(watched);String token=wdb.queryForObject("SELECT lease_token FROM b_trade_outbox WHERE event_id=?",String.class,event);var old=new TradeDelivery(delivery.eventId(),delivery.paymentId(),delivery.orderId(),delivery.userId(),delivery.body(),delivery.hash(),"PUBLISHED",0,token);var t=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(watched));t.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);new SettlementRepository(watched,t,orders,"zj-market","s01","c01").delivered(old,true,null);});
  var high=receipt(event,result(db,normal,2,"SUCCEEDED"),null);settlement.receive(high);settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_trade_inbox WHERE event_id=? AND state='WAITING_DEPENDENCY'",high.eventId())==1,"higher known version without full query waits");
  var verified=receipt(event,result(db,normal,2,"SUCCEEDED"),authority(db,normal,2,"SUCCEEDED"));settlement.receive(verified);settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND sync_status='ACCEPTED' AND accepted_version=2 AND accepted_status='SUCCEEDED'",normal)==1,"higher local-known version with full binding accepted");settlement.receive(verified);settlement.applyInbox(10000);settlement.receive(receipt(event,result(db,normal,1,"PENDING"),null));settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND accepted_version=2 AND accepted_status='SUCCEEDED'",normal)==1,"duplicate and old version never downgrade high water");
  String unknown=owned.get(1);settlement.receive(receipt(RefundOutbox.eventId(unknown,1),result(db,unknown,99,"SUCCEEDED"),null));settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND sync_status='REVIEW_REQUIRED' AND funds_status='SUCCEEDED'",unknown)==1,"unknown high version quarantines but retains funds");
  String conflict=owned.get(2);settlement.receive(receipt(RefundOutbox.eventId(conflict,2),result(db,conflict,2,"FAILED"),null));settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND sync_status='REVIEW_REQUIRED' AND funds_status='SUCCEEDED'",conflict)==1,"same version differing state quarantines");
  String wrong=owned.get(3);var wrongResult=result(db,wrong,12,"SUCCEEDED");String other=authority(db,wrong,12,"SUCCEEDED").replace("\"paidAmount\":\"", "\"paidAmount\":\"9");settlement.receive(receipt(RefundOutbox.eventId(wrong,1),wrongResult,other));settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND sync_status='REVIEW_REQUIRED'",wrong)==1,"full query differing original payment amount quarantines");
  String rejected=owned.get(4);var reject=receipt(RefundOutbox.eventId(rejected,2),result(db,rejected,2,"SUCCEEDED"),null);var rejectBody=(ObjectNode)JSON.readTree(reject.body());var rejectPayload=(ObjectNode)rejectBody.path("payload");rejectPayload.put("outcome","REJECTED");rejectPayload.put("code","REFUND_CONFLICT");rejectPayload.putNull("result");byte[] rejectWire=bytes(rejectBody);settlement.receive(new TradeReceipt(reject.producer(),reject.eventId(),reject.type(),ContractCodec.sha256(rejectWire),new String(rejectWire,StandardCharsets.UTF_8),reject.originalEventId()));settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND sync_status='REVIEW_REQUIRED' AND sync_error='A_REFUND_REJECTED' AND funds_status='SUCCEEDED'",rejected)==1,"deterministic A rejection retains actual refund");
  String foreign=owned.get(5);var forged=result(db,foreign,2,"SUCCEEDED");forged.put("outTradeNo","other-owned-order");settlement.receive(receipt(RefundOutbox.eventId(foreign,2),forged,null));settlement.applyInbox(10000);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE refund_id=? AND sync_status='REVIEW_REQUIRED' AND accepted_version=0",foreign)==1,"foreign order binding cannot acknowledge");
  for(String refund:owned)check(count(db,"SELECT COUNT(*) FROM b_inventory_reservation i JOIN b_refund f ON f.order_id=i.order_id WHERE f.refund_id=? AND i.state='HELD'",refund)==1,"refund receipt never releases inventory");
  Files.writeString(work.resolve("sync.txt"),"status=PASSED\nM1-M2-atomic-outbox/all-frozen-versions-DONE-review-backfill/idempotent-wire=PASSED\nbroker-ACK-not-accepted/actual-row-lock-expiry-and-replaced-token=PASSED\nhigher-known-with-full-query/unknown-higher/same-version-conflict/duplicate-old-no-downgrade=PASSED\noriginal-payment-mismatch-quarantine/funds-HELD-guard-retained=PASSED\n");
 }
}
